import math

class Order:

    DISH_KEY = "dish"
    PRICE_KEY = "price"
    COUNT_KEY = "count"

    def __init__(self):
        self._menu = []
        self._selected_dishes = []
        self._sales = {}

    @property
    def menu(self):
        return self._menu

    @property
    def selected_dishes(self):
        return self._selected_dishes

    @property
    def sales(self):
        return self._sales

    def add_dish(self, dish):
        if not self._has_sufficient_inventory(dish):
            return False
        self._decrement_inventory(dish)
        self._selected_dishes.append(dish)
        return True

    def _has_sufficient_inventory(self, dish):
        for menu_dish in self._menu:
            if menu_dish[self.DISH_KEY] == dish[self.DISH_KEY]:
                if menu_dish[self.COUNT_KEY] < dish[self.COUNT_KEY]:
                    return False
        return True

    def _decrement_inventory(self, dish):
        for menu_dish in self._menu:
            if menu_dish[self.DISH_KEY] == dish[self.DISH_KEY]:
                menu_dish[self.COUNT_KEY] -= dish[self.COUNT_KEY]
                break

    def calculate_total(self):
        return sum(
            dish[self.PRICE_KEY] * dish[self.COUNT_KEY] * self._sales[dish[self.DISH_KEY]]
            for dish in self._selected_dishes
        )

    def checkout(self):
        if len(self._selected_dishes) == 0:
            return False
        total = self.calculate_total()
        self._selected_dishes.clear()
        return total
